suppressPackageStartupMessages({library(data.table);library(ggplot2);library(jsonlite);library(png);library(ggrastr)});a<-commandArgs(TRUE);root<-normalizePath(a[1]);s<-a[2];out<-file.path(root,s);fig<-file.path(out,'figures');skill<-'/home/data/t070721/.agents/skills/jins-routine-plotting';for(f in c('theme','palettes','export'))source(file.path(skill,'common',paste0(f,'.R')));jin_setup();d<-fread(file.path(out,'bin_metadata.tsv.gz'));d[,QC:=ifelse(qc_keep,'Pass: UMI > 5','Excluded: UMI <= 5 / outside tissue')];tr<-read_json(file.path(out,'transform.json'),simplifyVector=TRUE);sh<-tr$model_image_shape_yx;sc<-tr$local_to_model_scale_xy;cr<-tr$fullres_crop_xyxy;mp<-tr$native_mpp;xx<-function(u)(cr[1]+(u+.5)/sc[1]-.5)*mp;yy<-function(u)-(cr[2]+(u+.5)/sc[2]-.5)*mp;assets<-file.path(dirname(root),'hd_major_annotation_v1',s,'spatial_assets');bg<-readPNG(file.path(assets,'whole_HE.png'));cov<-readPNG(file.path(assets,'outside_supplied_bins.png'));base<-ggplot(d,aes(x_um,-y_um))+annotation_raster(bg,xx(-.5),xx(sh[2]-.5),yy(sh[1]-.5),yy(-.5))+annotation_raster(cov,xx(-.5),xx(sh[2]-.5),yy(sh[1]-.5),yy(-.5))+coord_fixed(xlim=c(xx(-.5),xx(sh[2]-.5)),ylim=c(yy(sh[1]-.5),yy(-.5)),expand=FALSE)+jin_theme()+labs(x='Original x (um)',y='- Original y (um)');p<-base+geom_point_rast(aes(color=QC),size=.13,raster.dpi=300)+scale_color_manual(values=c('Pass: UMI > 5'='#80a2d3','Excluded: UMI <= 5 / outside tissue'='#d1495b'),name='Native input bins')+guides(color=guide_legend(override.aes=list(size=3)));jin_export(p,file.path(fig,'input_QC_coverage'),9,6.5,panel_width=6.5);p<-base+geom_point_rast(data=d[qc_keep==TRUE],aes(color=cell_unassigned_UMI/pmax(1,common_2um_UMI)),size=.13,raster.dpi=300)+scale_color_viridis_c(limits=c(0,1),name='Unassigned / supplied 2 um UMI',labels=scales::percent);jin_export(p,file.path(fig,'unassigned_UMI_contribution'),9,6.5,panel_width=6.5)
